// Kill a real candidate decision mutation using the same independent judge
// and GNL-RESULT accounting as the release CLI. No product file is edited.
import { spawnSync } from 'node:child_process';
import { mkdtempSync, mkdirSync, readFileSync, writeFileSync, existsSync, rmSync } from 'node:fs';
import { tmpdir } from 'node:os';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'../..'),out=resolve(process.argv[2]);
mkdirSync(out,{recursive:true});
const file=join(root,'server/decision/implementation.ts'),before='else if(owner(e)){';
const source=readFileSync(file,'utf8');if(!source.includes(before))throw Error('Candidate mutant anchor changed');
const dir=mkdtempSync(join(tmpdir(),'gnl-product-mutant-'));
try {
  const smoke=join(root,'scripts/nolim-replay/production-smoke.mjs');
  const baseline=spawnSync(process.execPath,['--experimental-strip-types',smoke,join(out,'baseline'),'--ordinary-only'],{encoding:'utf8',timeout:60000});
  writeFileSync(join(out,'baseline.log'),(baseline.stdout??'')+(baseline.stderr??''));
  const active=join(dir,'activated'),preload=join(dir,'mutant.mjs');
  const after=`else if(owner(e) && (r.snapshot?.input as any)?.command === 'printf fixture')outcome=approval(e,'base',[]);\n ${before}`;
  writeFileSync(preload,`import {registerHooks} from 'node:module';import {writeFileSync} from 'node:fs';registerHooks({load(url,ctx,next){const r=next(url,ctx);if(url===${JSON.stringify(pathToFileURL(file).href)}){const s=typeof r.source==='string'?r.source:Buffer.from(r.source).toString();if(!s.includes(${JSON.stringify(before)}))throw Error('anchor');writeFileSync(${JSON.stringify(active)},'applied');return {...r,source:s.replace(${JSON.stringify(before)},${JSON.stringify(after)})};}return r;}});`);
  const mutant=spawnSync(process.execPath,['--experimental-strip-types',smoke,join(out,'mutant'),'--ordinary-only'],{encoding:'utf8',timeout:60000,
    env:{...process.env,NODE_OPTIONS:`--import=${pathToFileURL(preload).href}`}});
  writeFileSync(join(out,'mutant.log'),(mutant.stdout??'')+(mutant.stderr??''));
  const killed=baseline.status===0&&mutant.status===1&&existsSync(active)&&/GNL-RESULT rows=1 pass=0 nonwipe_cards=1 refusals=0 skipped=0/.test(mutant.stdout??'');
  const report={mode:'fake-only candidate build mutation',releaseGate:false,baselineExit:baseline.status,mutantExit:mutant.status,activated:existsSync(active),killed,verdict:killed?'PASS':'FAIL'};
  writeFileSync(join(out,'verdict.json'),JSON.stringify(report,null,2)+'\n');console.log(JSON.stringify(report));if(!killed)process.exitCode=1;
}finally{rmSync(dir,{recursive:true,force:true});}

